import json, os, re, sys

SEL = "C:/Users/Administrator/.dsh/cache/memory-audit/select.json"
d = json.load(open(SEL, encoding="utf-8"))
ROOT = "D:/repository"
SKIP = {"skills", "OpenViking", "all", ".git", "node_modules", "dist", "build", ".tmp", "unpackage"}

# 1) build basename -> fullpaths index over repo projects
idx = {}
for repo in os.listdir(ROOT):
    rp = os.path.join(ROOT, repo)
    if not os.path.isdir(rp) or repo in SKIP:
        continue
    for dp, dns, fns in os.walk(rp):
        dns[:] = [x for x in dns if x not in SKIP and not x.startswith(".")]
        for f in fns:
            if f.endswith((".vue", ".js", ".ts", ".scss", ".css", ".json", ".py", ".mjs", ".jsx", ".tsx")):
                idx.setdefault(f, []).append(os.path.join(dp, f))

EXT = "(?:vue|js|ts|scss|css|json|py|mjs|jsx|tsx)"
def firstline(c):
    for ln in c.splitlines():
        ln = ln.strip()
        if ln.startswith("#"):
            return ln.lstrip("#").strip()[:60]
    return c.strip().splitlines()[0][:60] if c.strip() else ""

def project(c):
    m = re.search(r"所属项目[：:]\s*([^\n\\]+)", c)
    return (m.group(1).strip() if m else "?")[:18]

lines = []
for i, c in enumerate(d["candidates"]):
    content = c["content"].replace("\\n", "\n")
    # filenames mentioned (bare or path)
    fmatches = re.findall(r"[A-Za-z0-9_\u4e00-\u9fff.\-/\\]+\.(?:" + EXT + r")", content)
    bases = set()
    for f in fmatches:
        b = os.path.basename(f.replace("\\", "/"))
        if b:
            bases.add(b)
    hit_files = [b for b in bases if b in idx]
    # privacy placeholder
    priv = "{{ov_privacy:" in content
    # key symbols in backticks: identifiers length>=4, exclude filenames/paths/numbers/uuid
    syms = re.findall(r"`([^`\n]{4,60})`", content)
    syms = [s for s in syms if not re.search(r"\.(?:" + EXT + r")$", s)
            and "/" not in s and "\\" not in s
            and not re.fullmatch(r"[0-9a-fA-F\-]+", s)
            and re.search(r"[A-Za-z]", s)]
    syms = list(dict.fromkeys(syms))[:14]
    # search syms inside hit files content (bounded)
    blob = ""
    for b in hit_files[:6]:
        for p in idx[b][:2]:
            try:
                blob += open(p, encoding="utf-8", errors="ignore").read()[:200000]
            except Exception:
                pass
    sym_hit = [s for s in syms if s in blob]
    lines.append(
        "IDX %d | %s | %s | files %d/%d | sym %d/%d | priv=%s"
        % (i, project(content), firstline(content), len(hit_files), len(bases),
           len(sym_hit), len(syms), priv)
    )
    if syms:
        lines.append("   syms: " + ", ".join(("[+" + s + "]" if s in sym_hit else "[-" + s + "]") for s in syms))
    lines.append("   hitfiles: " + ", ".join(sorted(hit_files)[:12]))

open("C:/Users/Administrator/.dsh/cache/memory-audit/audit_check.txt", "w", encoding="utf-8").write("\n".join(lines))
print("done", len(lines), "lines")

